 build:task('build','Convert Hours','Define minutes(hours), returning hours multiplied by 60. It must accept decimal hours.','def minutes(hours):\n    pass','def minutes(hours):\n    return hours * 60',[['Decimal hours work','minutes(1.5) == 90'],['Zero works','minutes(0) == 0']],'Keep input and print outside this calculation function.'),
 repair:task('repair','Recognize Quit','Fix is_quit so it accepts q with spaces or capital letters.','def is_quit(command):\n    return command == "q"','def is_quit(command):\n    return command.strip().lower() == "q"',[['Quit is recognized','is_quit(" Q ") and is_quit("q")'],['Other commands are not quit','not is_quit("1") and not is_quit("")']],'Normalize the text before comparing it.'),
 practice:[task('average','Add an Average Feature','Define average(a, b). Return the mean of the two numbers.','def average(a, b):\n    pass','def average(a, b):\n    return (a + b) / 2',[['Decimal and whole inputs work','average(2,5) == 3.5 and average(1.5,2.5) == 2'],['Negative values work','average(-2,2) == 0']],'Add before dividing; use parentheses.'),task('command','Check Menu Commands','Define valid_command(text). Accept 1, 2, or q after stripping spaces and lowercasing. Return a Boolean.','def valid_command(text):\n    pass','def valid_command(text):\n    return text.strip().lower() in ["1", "2", "q"]',[['Valid choices work','valid_command("1") and valid_command(" 2 ") and valid_command("Q")'],['Invalid choices are rejected','not valid_command("") and not valid_command("3")']],'Use in with a list of allowed commands.')],
 homework:task('hw','Build a Command Router','Define calculate(command, a, b). Accept add or average, ignoring spaces and case. Return the result; raise ValueError for another command.','def calculate(command, a, b):\n    pass','def calculate(command, a, b):\n    command = command.strip().lower()\n    if command == "add":\n        return a + b\n    if command == "average":\n        return (a + b) / 2\n    raise ValueError("Unknown command")',[['Both calculations work','calculate(" ADD ",2,3) == 5 and calculate("average",1,2) == 1.5'],['Unknown commands are rejected','_raises(ValueError, lambda: calculate("other",1,2))']],'Make each valid branch return. Raise an error after those branches.'),
 projectTitle:'A Personal Toolkit',brief:'Extend a working menu with tools that share a consistent input flow.',milestones:[['Trace the menu','Run a valid choice, an invalid choice, and q. Explain which functions run.'],['Add a feature','Add a distance or temperature converter with its own function and menu option.'],['Protect the inputs','Choose which values your feature accepts. Reject invalid values and return to the menu.']],tests:['Try a decimal number and a non-number.','Use two tools in one run.','Quit from the main menu.'],extras:['Add a history of the last five answers.','Add a help command explaining each option.'],
